public class Rectangle extends Shape {
    private double width, height;     // added
    public Rectangle(double x, double y,
                     double w, double h) {
        super(x, y);                  // Shape's constructor
        width = w; height = h;
    }
    public double findArea() { return width * height; }
}

public class Disc extends Circle {
    private double thickness;
    public Disc(double x, double y, double rad, double t) {
        super(x, y, rad);       // must be line 1
        thickness = t;
    }
    public double findVolume() {
        return super.findArea() * thickness; // Circle's area
    }
    public void print() {
        System.out.println("Disc print() method: ");
        super.print();          // Circle's print()
        System.out.println("Thickness = " + thickness);
    }
}

